import * as Phaser from "phaser";
import { DEFAULT_UI_TEXT_STYLE, STORY_FLAG } from "../../common/constants";
import { getSceneDataManager } from "../../common/data-manager";
import { CUSTOM_EVENTS, EVENT_BUS } from "../../common/event-bus";
import type { StartSpotTheDifferenceData } from "../../entities/npcs/npc-types";
import { SCENE_KEYS } from "../scene-keys";

type DiffObject = {
  id: number;
  x: number;
  y: number;
  width: number;
  height: number;
  identifier: string;
};

type SpotTheDiffData = {
  imageKey: string;
  diffs: DiffObject[];
};

const TOTAL_IMAGES = 2; // Number of images to show
const TIME_LIMIT_SECONDS = 60; // 1 minute total
const WRONG_GUESS_PENALTY_SECONDS = 10;
const DIFFS_PER_IMAGE = 5;

export class SpotTheDifferenceScene extends Phaser.Scene {
  #currentImageIndex = 0;
  #selectedImages: SpotTheDiffData[] = [];
  #foundDiffs = new Set<string>(); // Track found diff identifiers
  #timeRemaining = TIME_LIMIT_SECONDS;
  #jsTimerInterval?: number;
  #imageSprite?: Phaser.GameObjects.Image;
  #overlay?: Phaser.GameObjects.Graphics;
  #diffCounterText?: Phaser.GameObjects.Text;
  #imageNumberText?: Phaser.GameObjects.Text;
  #timerText?: Phaser.GameObjects.Text;
  #storyFlag?: string;
  #imageKeys?: string[]; // Image keys provided by caller
  #diffIndicators: Phaser.GameObjects.Container[] = []; // Visual indicators for found diffs

  constructor() {
    super(SCENE_KEYS.SPOT_THE_DIFFERENCE_SCENE);
  }

  init(data?: StartSpotTheDifferenceData): void {
    if (data?.storyFlag) {
      this.#storyFlag = data.storyFlag;
    }
    if (data?.imageKeys && data.imageKeys.length > 0) {
      this.#imageKeys = data.imageKeys;
    }
  }

  create(): void {
    // Require image keys from caller
    if (!this.#imageKeys || this.#imageKeys.length === 0) {
      console.error(
        "SpotTheDifferenceScene: imageKeys must be provided in init data",
      );
      this.scene.stop();
      return;
    }

    // Parse all available images
    const availableImages: SpotTheDiffData[] = [];

    // Parse each spot image using the configured image keys
    for (const imageKey of this.#imageKeys) {
      const spotData = this.cache.json.get(`${imageKey}_data`) as
        | {
            layers: {
              name: string;
              type: string;
              objects?: {
                id: number;
                x: number;
                y: number;
                width: number;
                height: number;
                properties?: {
                  name: string;
                  value: string;
                }[];
              }[];
            }[];
          }
        | undefined;

      if (!spotData) {
        continue;
      }

      const diffsLayer = spotData.layers.find(
        (layer) => layer.name === "diffs" && layer.type === "objectgroup",
      );

      if (diffsLayer?.objects) {
        availableImages.push({
          imageKey,
          diffs: diffsLayer.objects
            .filter((obj) =>
              obj.properties?.some((p) => p.name === "identifier"),
            )
            .map((obj) => ({
              id: obj.id,
              x: obj.x,
              y: obj.y,
              width: obj.width,
              height: obj.height,
              identifier:
                obj.properties?.find((p) => p.name === "identifier")?.value ??
                "",
            })),
        });
      }
    }

    // Randomly select 2 images (or all available if less than 2)
    const numToSelect = Math.min(TOTAL_IMAGES, availableImages.length);
    const shuffled = [...availableImages].sort(() => Math.random() - 0.5);
    this.#selectedImages = shuffled.slice(0, numToSelect);

    // Reset game state
    this.#currentImageIndex = 0;
    this.#foundDiffs.clear();
    this.#timeRemaining = TIME_LIMIT_SECONDS;

    // Create UI
    this.#createUI();
    this.#loadCurrentImage();

    // Start timer
    this.#startTimer();

    // Listen for ESC to exit
    this.input.keyboard?.on("keydown-ESC", () => {
      this.#close(false);
    });
  }

  #createUI(): void {
    const centerX = this.cameras.main.centerX;
    const screenHeight = this.cameras.main.height;

    // Timer text (top center)
    this.#timerText = this.add
      .text(centerX, 30, this.#formatTime(this.#timeRemaining), {
        ...DEFAULT_UI_TEXT_STYLE,
        fontSize: "32px",
      })
      .setOrigin(0.5, 0)
      .setStroke("#ffffff", 2)
      .setDepth(2); // Above overlay and image

    // Image number text (top left)
    this.#imageNumberText = this.add
      .text(
        20,
        30,
        `Image ${this.#currentImageIndex + 1}/${this.#selectedImages.length}`,
        {
          ...DEFAULT_UI_TEXT_STYLE,
          fontSize: "28px",
        },
      )
      .setOrigin(0, 0)
      .setStroke("#ffffff", 2)
      .setDepth(2); // Above overlay and image

    // Diff counter (bottom center)
    this.#diffCounterText = this.add
      .text(centerX, screenHeight - 40, this.#getDiffCounterText(), {
        ...DEFAULT_UI_TEXT_STYLE,
        fontSize: "32px",
      })
      .setOrigin(0.5, 1)
      .setStroke("#ffffff", 2)
      .setDepth(2); // Above overlay and image
  }

  #loadCurrentImage(): void {
    if (this.#currentImageIndex >= this.#selectedImages.length) {
      // All images completed
      this.#win();
      return;
    }

    const currentImage = this.#selectedImages[this.#currentImageIndex];
    const centerX = this.cameras.main.centerX;
    const centerY = this.cameras.main.centerY;

    // Remove previous image, overlay, and indicators if exists
    this.#imageSprite?.destroy();
    this.#overlay?.destroy();
    this.#diffIndicators.forEach((indicator) => {
      indicator.destroy();
    });
    this.#diffIndicators = [];

    // Display current image (160x160px native, displayed at 2x = 320x320px, centered)
    this.#imageSprite = this.add
      .image(centerX, centerY, currentImage.imageKey)
      .setOrigin(0.5)
      .setInteractive({ useHandCursor: true })
      .on("pointerdown", (pointer: Phaser.Input.Pointer) => {
        this.#handleClick(pointer.x, pointer.y);
      });

    // Create grey overlay covering the entire screen
    const screenWidth = this.cameras.main.width;
    const screenHeight = this.cameras.main.height;

    this.#overlay = this.add.graphics();
    this.#overlay.fillStyle(0x000000, 0.7); // Grey overlay with 70% opacity
    this.#overlay.fillRect(0, 0, screenWidth, screenHeight);
    this.#overlay.setDepth(0); // Bottom layer

    // Make image clickable and zoom to 2x
    this.#imageSprite.setDisplaySize(320, 320);
    this.#imageSprite.setDepth(1); // On top of the overlay

    // Show indicators for already found diffs in this image
    this.#showFoundDiffIndicators(currentImage);

    // Update UI
    this.#updateUI();
  }

  #showFoundDiffIndicators(currentImage: SpotTheDiffData): void {
    if (!this.#imageSprite) {
      return;
    }

    const imageCenterX = this.#imageSprite.x;
    const imageCenterY = this.#imageSprite.y;
    const scale = 2; // Image is displayed at 2x

    for (const diff of currentImage.diffs) {
      const diffKey = `${currentImage.imageKey}_${diff.identifier}`;
      if (this.#foundDiffs.has(diffKey)) {
        // Calculate position in screen coordinates (accounting for 2x zoom)
        const diffCenterX = diff.x + diff.width / 2;
        const diffCenterY = diff.y + diff.height / 2;
        const screenX = imageCenterX - 160 + diffCenterX * scale;
        const screenY = imageCenterY - 160 + diffCenterY * scale;

        this.#createDiffIndicator(screenX, screenY);
      }
    }
  }

  #createDiffIndicator(x: number, y: number): void {
    // Create a container for the indicator
    const container = this.add.container(x, y);

    // Draw a green circle
    const circle = this.add.circle(0, 0, 12, 0x00ff00, 0.8);
    circle.setStrokeStyle(2, 0xffffff, 1);

    // Add a checkmark text
    const checkmark = this.add.text(0, 0, "✓", {
      fontSize: "16px",
      color: "#ffffff",
      fontStyle: "bold",
    });
    checkmark.setOrigin(0.5);

    container.add([circle, checkmark]);
    container.setDepth(1000); // Ensure it's above the image

    this.#diffIndicators.push(container);
  }

  #handleClick(clickX: number, clickY: number): void {
    const currentImage = this.#selectedImages[this.#currentImageIndex];
    if (!currentImage || !this.#imageSprite) {
      return;
    }

    // Convert screen coordinates to image coordinates
    // Image is displayed at 2x (320x320) but coordinates are in original 160x160 space
    const screenX =
      clickX - (this.#imageSprite.x - this.#imageSprite.displayWidth / 2);
    const screenY =
      clickY - (this.#imageSprite.y - this.#imageSprite.displayHeight / 2);
    // Scale down by 2x to match original image coordinate space
    const imageX = (screenX / this.#imageSprite.displayWidth) * 160;
    const imageY = (screenY / this.#imageSprite.displayHeight) * 160;

    // Check if click is within any diff bounding box for the current image
    for (const diff of currentImage.diffs) {
      // Create a unique identifier for this diff in this image
      const diffKey = `${currentImage.imageKey}_${diff.identifier}`;

      if (this.#foundDiffs.has(diffKey)) {
        continue; // Already found
      }

      if (
        imageX >= diff.x &&
        imageX <= diff.x + diff.width &&
        imageY >= diff.y &&
        imageY <= diff.y + diff.height
      ) {
        // Found a diff!
        this.#foundDiffs.add(diffKey);

        // Create visual indicator at the center of the diff
        if (this.#imageSprite) {
          const diffCenterX = diff.x + diff.width / 2;
          const diffCenterY = diff.y + diff.height / 2;
          const imageCenterX = this.#imageSprite.x;
          const imageCenterY = this.#imageSprite.y;
          const scale = 2; // Image is displayed at 2x
          const screenX = imageCenterX - 160 + diffCenterX * scale;
          const screenY = imageCenterY - 160 + diffCenterY * scale;
          this.#createDiffIndicator(screenX, screenY);
        }

        this.#updateUI();

        // Check if all diffs in current image are found
        const currentImageFoundDiffs = currentImage.diffs.filter((d) =>
          this.#foundDiffs.has(`${currentImage.imageKey}_${d.identifier}`),
        );
        if (currentImageFoundDiffs.length >= DIFFS_PER_IMAGE) {
          // Move to next image
          this.#currentImageIndex++;
          this.#loadCurrentImage();
        }
        return;
      }
    }

    // Wrong guess - penalize time
    this.#timeRemaining = Math.max(
      0,
      this.#timeRemaining - WRONG_GUESS_PENALTY_SECONDS,
    );
    this.#updateTimer();
  }

  #updateUI(): void {
    if (this.#imageNumberText) {
      this.#imageNumberText.setText(
        `Image ${this.#currentImageIndex + 1}/${this.#selectedImages.length}`,
      );
    }

    if (this.#diffCounterText) {
      this.#diffCounterText.setText(this.#getDiffCounterText());
    }
  }

  #getDiffCounterText(): string {
    const currentImage = this.#selectedImages[this.#currentImageIndex];
    if (!currentImage) {
      return "All images completed!";
    }

    const foundInCurrent = currentImage.diffs.filter((d) =>
      this.#foundDiffs.has(`${currentImage.imageKey}_${d.identifier}`),
    ).length;
    const isHedges = this.#storyFlag === STORY_FLAG.spot_the_diff_hedges;
    const label = isHedges ? "Puzzmon found" : "Diffs found";
    return `${label}: ${foundInCurrent}/${DIFFS_PER_IMAGE}`;
  }

  #startTimer(): void {
    // Use JavaScript setInterval instead of Phaser timer so it continues
    // even when the window loses focus
    this.#jsTimerInterval = window.setInterval(() => {
      this.#timeRemaining--;
      this.#updateTimer();

      if (this.#timeRemaining <= 0) {
        this.#lose();
      }
    }, 1000);
  }

  #updateTimer(): void {
    if (this.#timerText) {
      this.#timerText.setText(this.#formatTime(this.#timeRemaining));
    }
  }

  #formatTime(seconds: number): string {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, "0")}`;
  }

  #win(): void {
    if (this.#jsTimerInterval !== undefined) {
      clearInterval(this.#jsTimerInterval);
      this.#jsTimerInterval = undefined;
    }

    // Complete story flag if provided
    if (this.#storyFlag) {
      const dataManager = getSceneDataManager(this);
      dataManager.setFlagToCompleted(this.#storyFlag);
      dataManager.completeInteraction(this.#storyFlag);
    }

    const isHedges = this.#storyFlag === STORY_FLAG.spot_the_diff_hedges;
    const winMessage = isHedges
      ? "You found all the Puzzmon!"
      : "Congratulations! You found everything!";

    EVENT_BUS.emit(CUSTOM_EVENTS.DIALOG_START, {
      messages: [winMessage],
    });

    this.#close(true);
  }

  #lose(): void {
    if (this.#jsTimerInterval !== undefined) {
      clearInterval(this.#jsTimerInterval);
      this.#jsTimerInterval = undefined;
    }

    const isHedges = this.#storyFlag === STORY_FLAG.spot_the_diff_hedges;
    const message = isHedges
      ? "Time's up! You didn't find all the Puzzmon in time."
      : "Time's up! You didn't find all the differences in time.";
    EVENT_BUS.emit(CUSTOM_EVENTS.DIALOG_START, {
      messages: [message],
    });

    this.#close(false);
  }

  #close(success: boolean): void {
    // Clean up
    if (this.#jsTimerInterval !== undefined) {
      clearInterval(this.#jsTimerInterval);
      this.#jsTimerInterval = undefined;
    }
    this.#imageSprite?.destroy();
    this.#overlay?.destroy();
    this.#diffIndicators.forEach((indicator) => {
      indicator.destroy();
    });
    this.#diffIndicators = [];
    this.#diffCounterText?.destroy();
    this.#imageNumberText?.destroy();
    this.#timerText?.destroy();

    // Emit completion event
    EVENT_BUS.emit(CUSTOM_EVENTS.SPOT_THE_DIFFERENCE_COMPLETE, {
      success,
    });

    // Stop this scene
    this.scene.stop();
  }
}
